import java.io.*;
import java.util.*;

class Solution {
    static class Entry {
        int count;
        char ch;
        Entry(int count, char ch) {
            this.count = count;
            this.ch = ch;
        }
    }

    public String longestDiverseString(int a, int b, int c) {
        PriorityQueue<Entry> pq = new PriorityQueue<>(
            (x, y) -> x.count != y.count
                ? Integer.compare(y.count, x.count)
                : Character.compare(x.ch, y.ch)
        );

        if (a > 0) pq.offer(new Entry(a, 'a'));
        if (b > 0) pq.offer(new Entry(b, 'b'));
        if (c > 0) pq.offer(new Entry(c, 'c'));

        StringBuilder result = new StringBuilder();

        while (!pq.isEmpty()) {
            Entry first = pq.poll();

            if (result.length() >= 2
                    && result.charAt(result.length() - 1) == first.ch
                    && result.charAt(result.length() - 2) == first.ch) {
                if (pq.isEmpty()) break;

                Entry second = pq.poll();
                result.append(second.ch);
                second.count--;
                if (second.count > 0) pq.offer(second);
                pq.offer(first);
            } else {
                result.append(first.ch);
                first.count--;
                if (first.count > 0) pq.offer(first);
            }
        }

        return result.toString();
    }
}

