#include <bits/stdc++.h>
using namespace std;

class Solution {
    struct Entry {
        int count;
        char ch;
    };

    struct Compare {
        bool operator()(const Entry& x, const Entry& y) const {
            if (x.count != y.count) return x.count < y.count;
            return x.ch > y.ch;
        }
    };

public:
    string longestDiverseString(int a, int b, int c) {
        priority_queue<Entry, vector<Entry>, Compare> pq;

        if (a > 0) pq.push({a, 'a'});
        if (b > 0) pq.push({b, 'b'});
        if (c > 0) pq.push({c, 'c'});

        string result;

        while (!pq.empty()) {
            Entry first = pq.top();
            pq.pop();

            if (result.size() >= 2 &&
                result[result.size() - 1] == first.ch &&
                result[result.size() - 2] == first.ch) {

                if (pq.empty()) break;

                Entry second = pq.top();
                pq.pop();

                result.push_back(second.ch);
                --second.count;
                if (second.count > 0) pq.push(second);
                pq.push(first);
            } else {
                result.push_back(first.ch);
                --first.count;
                if (first.count > 0) pq.push(first);
            }
        }

        return result;
    }
};

