function longestDiverseString(a, b, c) {
    const heap = [];
    const push = (count, ch) => {
        if (count > 0) heap.push({ count, ch });
        heap.sort((x, y) => y.count - x.count || x.ch.localeCompare(y.ch));
    };
    const pop = () => {
        const item = heap.shift();
        return item;
    };

    push(a, "a");
    push(b, "b");
    push(c, "c");

    const result = [];

    while (heap.length) {
        const first = pop();

        if (
            result.length >= 2 &&
            result[result.length - 1] === first.ch &&
            result[result.length - 2] === first.ch
        ) {
            if (!heap.length) break;

            const second = pop();
            result.push(second.ch);
            second.count--;
            if (second.count > 0) push(second.count, second.ch);
            push(first.count, first.ch);
        } else {
            result.push(first.ch);
            first.count--;
            if (first.count > 0) push(first.count, first.ch);
        }
    }

    return result.join("");
}

