#include <stdio.h>
#include <stdlib.h>
#include <string.h>

char* longestDiverseString(int a, int b, int c) {
    int count[3] = {a, b, c};
    const char letters[3] = {'a', 'b', 'c'};
    char* result = (char*)malloc(301);
    if (!result) exit(EXIT_FAILURE);

    int len = 0;

    while (1) {
        int best = -1;
        for (int i = 0; i < 3; ++i) {
            if (count[i] > 0 && (best == -1 || count[i] > count[best])) {
                best = i;
            }
        }
        if (best == -1) break;

        if (len >= 2 &&
            result[len - 1] == letters[best] &&
            result[len - 2] == letters[best]) {

            int second = -1;
            for (int i = 0; i < 3; ++i) {
                if (i == best || count[i] == 0) continue;
                if (second == -1 || count[i] > count[second]) {
                    second = i;
                }
            }

            if (second == -1) break;

            result[len++] = letters[second];
            count[second]--;
        } else {
            result[len++] = letters[best];
            count[best]--;
        }
    }

    result[len] = '\0';
    return result;
}

